"use strict";exports.id=2164,exports.ids=[2164],exports.modules={32164:(a,b,c)=>{c.d(b,{sI:()=>e});var d=c(43713);let e={"purchase-request":{key:"purchase-request",endpoint:"purchase-requests",table:"purchase_requests",items:"purchase_request_items",parentKey:"request_id",noColumn:"request_no",dateColumn:"request_date",party:"supplier",hasSalesperson:!1,inTransferChain:!1,module:"purchase_requests",numbering:{module:"PURCHASES",type:"Purchase Request"},numberLabel:"Request No.",noun:"purchase request",label:"Purchase Request",plural:"Purchase Requests",view:"purchase-requests",printTitle:"Purchase Request",subtitle:"What somebody inside the company has asked to buy, and who they want it from. A request commits nothing and posts nothing — the order raised from it is the commitment.",statuses:["draft","approved","rejected","cancelled"],editable:["draft"],transitions:{approve:(0,d.Ob)(),reject:(0,d.yV)(["draft","approved"]),cancel:(0,d.bO)(["draft","approved"]),reopen:(0,d.WS)(["rejected","cancelled"])},extras:[{column:"required_date",label:"Required By",kind:"date",hint:"When the goods are needed. Leave blank if there is no deadline.",print:"Required By",list:"Required",notBefore:"request_date",notBeforeReason:"A request cannot be needed before the day it was raised."},{column:"department",label:"Department",kind:"text",maxLength:255,hint:"Who is asking. Printed on the request, and what a purchase report groups by.",print:"Department",list:"Department"},{column:"requester",label:"Requested By",kind:"text",maxLength:255,hint:"The person, not the department.",print:"Requested By"},{column:"purpose",label:"Purpose",kind:"text",maxLength:2e3,hint:"Why it is needed. A request with no purpose is a request somebody has to ask about before approving.",print:"Purpose"}],hasPaymentTerms:!0,posts:!1,registerNote:"A purchase request posts nothing and orders nothing. It records that somebody asked, and who approved or refused. Turning one into a purchase order is not automated yet: the schema has `purchase_orders.source_request_id` for the link, but no purchase document is in the transfer chain, so the order is raised here and the two are related by their numbers rather than by line quantities. That is stated rather than hidden behind a Convert button that would claim a link with nothing behind it."},"purchase-order":{key:"purchase-order",endpoint:"purchase-orders",table:"purchase_orders",items:"purchase_order_items",parentKey:"order_id",noColumn:"order_no",dateColumn:"order_date",party:"supplier",hasSalesperson:!1,inTransferChain:!1,module:"purchase_orders",numbering:{module:"PURCHASES",type:"Purchase Order"},numberLabel:"Order No.",noun:"purchase order",label:"Purchase Order",plural:"Purchase Orders",view:"purchase-orders",printTitle:"Purchase Order",subtitle:"What the company has committed to buy. An order posts nothing — the supplier invoice raised against it is what reaches the accounts.",statuses:["draft","approved","rejected","cancelled","completed"],editable:["draft"],transitions:{approve:(0,d.Ob)(),complete:{from:["approved"],to:"completed",past:"marked completed",label:"Mark Completed",icon:"bi-check2-all"},reject:(0,d.yV)(["draft","approved"]),cancel:(0,d.bO)(["draft","approved"]),reopen:(0,d.WS)(["rejected","cancelled"])},extras:[{column:"delivery_date",label:"Delivery Date",kind:"date",hint:"When the supplier is to deliver. Printed on the order, so it is what they are held to.",print:"Delivery Date",list:"Delivery",notBefore:"order_date",notBeforeReason:"An order cannot be delivered before the day it was placed."},{column:"department",label:"Department",kind:"text",maxLength:100,hint:"Who the purchase is for.",print:"Department",list:"Department"},{column:"requester",label:"Requested By",kind:"text",maxLength:255,hint:"The person who asked for it.",print:"Requested By"},{column:"purpose",label:"Purpose",kind:"text",maxLength:2e3,hint:"What it is for. Printed on the order.",print:"Purpose"}],hasPaymentTerms:!0,posts:!1,registerNote:"A purchase order posts nothing to the ledger. It is a commitment, not a cost — the cost arrives with the supplier invoice. Mark Completed is a PERSON'S decision here, unlike a sales order where processing and completed are derived from delivered quantities: no purchase document is in the transfer chain yet, so there are no received quantities to derive it from, and a button somebody presses is more honest than a status nothing sets."},"goods-received-note":{key:"goods-received-note",endpoint:"goods-received-notes",table:"goods_received_notes",items:"goods_received_note_items",parentKey:"grn_id",noColumn:"grn_no",dateColumn:"grn_date",party:"supplier",hasSalesperson:!1,inTransferChain:!1,module:"purchase_grn",numbering:{module:"PURCHASES",type:"Goods Received Note"},numberLabel:"Ref. No.",noun:"goods received note",label:"Goods Received Note",plural:"Goods Received Notes",view:"purchase-grn",printTitle:"Goods Received Note",subtitle:"What actually arrived, from whom, and against which delivery note. Goods move, money does not — under this chart a GRN posts nothing.",statuses:["draft","pending","approved","rejected"],editable:["draft"],transitions:{submit:{from:["draft"],to:"pending",past:"submitted",label:"Submit for Checking",icon:"bi-box-arrow-in-right"},approve:(0,d.Ob)(["pending"]),reject:(0,d.yV)(["draft","pending"]),reopen:(0,d.WS)(["pending","rejected"])},extras:[{column:"delivery_order_no",label:"Their D.O. No.",kind:"text",maxLength:100,hint:"The number on the delivery note the driver handed over. This is what a dispute is settled by.",print:"D.O. No.",list:"Their D.O.",printAlways:!0}],hasPaymentTerms:!0,posts:!1,registerNote:"A goods received note posts nothing to the ledger. There is no perpetual stock ledger in this chart, so receiving goods has no journal — the supplier invoice is what reaches the accounts. Note that this document has NO cancelled status: its live enum is draft, pending, approved and rejected. A GRN that should not have been raised is rejected, which keeps the number and the reason on record."},"supplier-invoice":{key:"supplier-invoice",endpoint:"supplier-invoices",table:"supplier_invoices",items:"supplier_invoice_items",parentKey:"invoice_id",noColumn:"invoice_no",dateColumn:"invoice_date",party:"supplier",hasSalesperson:!1,inTransferChain:!1,module:"purchase_invoices",numbering:{module:"PURCHASES",type:"Supplier Invoice"},numberLabel:"Ref. No.",noun:"supplier invoice",label:"Supplier Invoice",plural:"Supplier Invoices",view:"purchase-invoices",printTitle:"Supplier Invoice",subtitle:"What a supplier has billed the company. It creates the payable balance a payment is applied to — an approved invoice is not edited, it is credited.",statuses:["draft","approved","rejected","cancelled"],editable:["draft"],transitions:{approve:(0,d.Ob)(),reject:(0,d.yV)(["draft","approved"]),cancel:(0,d.bO)(["draft"]),reopen:(0,d.WS)(["rejected","cancelled"])},extras:[{column:"due_date",label:"Due Date",kind:"date",hint:"When the supplier expects payment. Leave blank to age from the invoice date.",print:"Due Date",list:"Due",notBefore:"invoice_date",notBeforeReason:"An invoice cannot fall due before the day it was issued."},{column:"supplier_invoice_no",label:"Their Invoice No.",kind:"text",maxLength:100,hint:"The number the SUPPLIER put on the invoice. This is what they will quote and what a payment is reconciled against — not the Ref. No. above, which is ours.",print:"Their Invoice No.",list:"Their No.",printAlways:!0},{column:"delivery_order_no",label:"Their D.O. No.",kind:"text",maxLength:100,hint:"The delivery note this invoice covers, when there was one.",print:"D.O. No."},{column:"lhdn_status",label:"Self-billed e-Invoice",kind:"readonly"}],hasPaymentTerms:!0,posts:!0,payable:{direction:"increase"},theirNoColumn:"supplier_invoice_no",registerNote:"A supplier invoice does NOT post itself. It is posted from General Ledger > Document Posting, the same place a sales invoice is. What has been paid is recorded in Money > Payables > Make Payments, and the Balance column here is derived from the payments allocated and the credit notes applied — never a stored figure. Rejecting an invoice REMOVES it from what the company owes, because a disputed invoice is not a debt; cancel it instead if it should never have been entered. The self-billed e-Invoice field is written by the MyInvois submission and cannot be typed here.",reversedBy:[{table:"supplier_credit_notes",column:"original_invoice_id",noun:"supplier credit note",noColumn:"credit_note_no"},{table:"supplier_debit_notes",column:"original_invoice_id",noun:"supplier debit note",noColumn:"debit_note_no"}]},"cash-purchase":{key:"cash-purchase",endpoint:"cash-purchases",table:"cash_purchases",items:"cash_purchase_items",parentKey:"cash_purchase_id",noColumn:"payment_no",dateColumn:"payment_date",party:"supplier",hasSalesperson:!1,inTransferChain:!1,module:"purchase_cash",numbering:{module:"PURCHASES",type:"Cash Purchase"},numberLabel:"Payment No.",noun:"cash purchase",label:"Cash Purchase",plural:"Cash Purchases",view:"purchase-cash",printTitle:"Cash Purchase",subtitle:"Bought and paid at the same moment. A cash purchase has no payment terms and never appears on an ageing report — the money is recorded against the account it came out of.",statuses:["draft","approved","cancelled"],editable:["draft"],transitions:{approve:(0,d.Ob)(),cancel:(0,d.bO)(["draft"]),reopen:(0,d.WS)(["cancelled"])},extras:[{column:"payment_method",label:"Paid By",kind:"select",options:"payment_methods",required:!0,maxLength:50,hint:"A closed list, because the column is an enum. A bank transfer is EFT.",print:"Paid By",list:"Paid By"},{column:"reference_no",label:"Payment Ref.",kind:"text",maxLength:100,hint:"Cheque number, transfer reference, terminal slip.",print:"Payment Ref."},{column:"paid_from_account_id",label:"Paid From",kind:"select",options:"bank_accounts",required:!0,snapshot:{codeColumn:"paid_from_account_code",nameColumn:"paid_from_account_name"},hint:"Cash and bank accounts only. This is the account the money came out of.",print:"Paid From",list:"Paid From"}],hasPaymentTerms:!1,posts:!0,registerNote:"A cash purchase is paid when it is made, so it has no payment terms, never appears on an ageing report and no payment is applied to it. Post it from General Ledger > Document Posting: the purchase or expense and input tax accounts are debited, and the selected bank or cash account is credited."},"supplier-credit-note":{key:"supplier-credit-note",endpoint:"supplier-credit-notes",table:"supplier_credit_notes",items:"supplier_credit_note_items",parentKey:"credit_note_id",noColumn:"credit_note_no",dateColumn:"credit_note_date",party:"supplier",hasSalesperson:!1,inTransferChain:!1,module:"purchase_credit_notes",numbering:{module:"PURCHASES",type:"Supplier Credit Note"},numberLabel:"Ref. No.",noun:"supplier credit note",label:"Supplier Credit Note",plural:"Supplier Credit Notes",view:"purchase-credit-notes",printTitle:"Supplier Credit Note",subtitle:"Reduces what the company owes a supplier — goods returned, an overcharge corrected. It REVERSES a purchase rather than continuing one, so it carries its own reason and the invoice it credits.",statuses:["draft","approved","rejected","cancelled"],editable:["draft"],transitions:{approve:(0,d.Ob)(),reject:(0,d.yV)(["draft","approved"]),cancel:(0,d.bO)(["draft"]),reopen:(0,d.WS)(["rejected","cancelled"])},extras:[{column:"reason",label:"Reason",kind:"text",maxLength:500,hint:"Why the supplier is crediting us. Printed on the note — a credit with no reason is a credit somebody has to ask about.",print:"Reason"},{column:"original_invoice_no",label:"Against Ref. No.",kind:"text",maxLength:50,hint:"The Ref. No. of the supplier invoice this credits — ours, not theirs. Matched exactly, and what it matched is what the balance is reduced against.",print:"Against Invoice",list:"Invoice"},{column:"supplier_credit_note_no",label:"Their Credit Note No.",kind:"text",maxLength:100,hint:"The number the SUPPLIER put on the credit note.",print:"Their Credit Note No."}],hasPaymentTerms:!0,posts:!0,payable:{direction:"decrease",appliedTo:"original_invoice_id"},adjusts:{table:"supplier_invoices",lookupColumn:"invoice_no",numberColumn:"original_invoice_no",idColumn:"original_invoice_id",noun:"supplier invoice"},theirNoColumn:"supplier_credit_note_no",registerNote:"A supplier credit note reduces what the company owes, against the supplier invoice named in Against Ref. No. That number is resolved to the invoice itself when the note is saved, and the note is refused if it names an invoice belonging to another supplier — a credit applied to the wrong invoice would leave one supplier looking overpaid and another looking unpaid. Like an invoice, it is posted from General Ledger > Document Posting."},"supplier-debit-note":{key:"supplier-debit-note",endpoint:"supplier-debit-notes",table:"supplier_debit_notes",items:"supplier_debit_note_items",parentKey:"debit_note_id",noColumn:"debit_note_no",dateColumn:"debit_note_date",party:"supplier",hasSalesperson:!1,inTransferChain:!1,module:"purchase_debit_notes",numbering:{module:"PURCHASES",type:"Supplier Debit Note"},numberLabel:"Ref. No.",noun:"supplier debit note",label:"Supplier Debit Note",plural:"Supplier Debit Notes",view:"purchase-debit-notes",printTitle:"Supplier Debit Note",subtitle:"A supplier charging MORE against an invoice already sent. Separate from a credit note because being charged more and being credited are opposite movements with different authority.",statuses:["draft","approved","rejected","cancelled"],editable:["draft"],transitions:{approve:(0,d.Ob)(),reject:(0,d.yV)(["draft","approved"]),cancel:(0,d.bO)(["draft"]),reopen:(0,d.WS)(["rejected","cancelled"])},extras:[{column:"reason",label:"Reason",kind:"text",maxLength:500,hint:"Why the supplier is charging more. Printed on the note.",print:"Reason"},{column:"original_invoice_no",label:"Against Ref. No.",kind:"text",maxLength:50,hint:"The Ref. No. of the supplier invoice this adds to — ours, not theirs.",print:"Against Invoice",list:"Invoice"},{column:"supplier_debit_note_no",label:"Their Debit Note No.",kind:"text",maxLength:100,hint:"The number the SUPPLIER put on the debit note. This is what a payment is reconciled against.",print:"Their Debit Note No."}],hasPaymentTerms:!0,posts:!0,payable:{direction:"increase"},adjusts:{table:"supplier_invoices",lookupColumn:"invoice_no",numberColumn:"original_invoice_no",idColumn:"original_invoice_id",noun:"supplier invoice"},theirNoColumn:"supplier_debit_note_no",registerNote:"A supplier debit note is kept separate from a credit note on purpose: owing more and owing less are opposite movements, and one screen for both puts the wrong one a click away. It is payable in its own right — a payment can be applied to it — and it ages from its own date, because the table has no due date column. Post it from General Ledger > Document Posting after approval."}}}};